import type { EngineType, SkillCatalog, SkillState, UnionEventType } from "../types";
import { inspectorStore } from "./InspectorStore";
import type { InspectorView } from "../types/inspector";

export function toggleSelectedElement(element: UnionEventType): void {
  inspectorStore.setState((prev) => ({
    ...prev,
    selectedElement: element.id === prev.selectedElement?.id ? undefined : element,
  }));
}

export function clearSelectedElement(): void {
  inspectorStore.setState((prev) => ({
    ...prev,
    selectedElement: undefined,
  }));
}

export function setInspectMode(enabled: boolean): void {
  inspectorStore.setState((prev) => ({ ...prev, inspectMode: enabled }));
}

export function setInspectorView(view: InspectorView): void {
  inspectorStore.setState((prev) => ({ ...prev, inspectorView: view }));
}

export function setEngineType(engineType: EngineType): void {
  inspectorStore.setState((prev) => ({ ...prev, engineType }));
}

export function setSkillCatalog(skillCatalog: SkillCatalog | null): void {
  inspectorStore.setState((prev) => ({ ...prev, skillCatalog }));
}

export function setSkillState(skillState: SkillState | null | undefined): void {
  // `undefined` (key absent from a tracker payload) keeps the previous state:
  // v1 payloads and payloads with a malformed skill_state never carry the key,
  // and clearing on those would blank the pane mid-conversation. `null` is the
  // explicit clear (e.g. when a new conversation starts).
  if (skillState === undefined) return;
  inspectorStore.setState((prev) => ({
    ...prev,
    skillState,
    // Remember the last skill that was actually active so the pane can keep
    // showing it between skills instead of dropping to an empty state. An
    // explicit clear (new conversation) resets it too.
    lastActiveSkillRef:
      skillState?.active_skill ?? (skillState === null ? null : prev.lastActiveSkillRef),
  }));
}
